#!/usr/bin/env bash
# Duplicate search on harrisiirak/cron-parser: issues and PRs, all states.
# Generated by upstream_scripts.py (QPB v1.6.1 [R]); regenerate rather than edit.
# The operator runs this. A failed search is logged as FAILED and the rest run.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
UPSTREAM=harrisiirak/cron-parser
OUT="$HERE/dup-search.out"
search() {
  local what="$1" query="$2" rc=0
  echo "### gh search $what --repo $UPSTREAM: $query"
  gh search "$what" --repo "$UPSTREAM" --limit 30 -- "$query" || rc=$?
  if [[ $rc -ne 0 ]]; then echo "FAILED: gh search $what (exit $rc)"; fi
  echo
}
{
  echo "# dup-search for $UPSTREAM, $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  echo; echo '## cron-parser-http-date-formats'
  search issues fromHTTP
  search prs fromHTTP
  search issues '"HTTP and RFC2822"'
  search prs '"HTTP and RFC2822"'
  search issues 'asctime currentDate'
  search prs 'asctime currentDate'
  search issues '"unhandled timestamp"'
  search prs '"unhandled timestamp"'
  search issues 'RFC 850 date string'
  search prs 'RFC 850 date string'
  search issues 'string date formats supported README'
  search prs 'string date formats supported README'
} > "$OUT" 2>&1
echo "Wrote $OUT. Give it to the agent (paste or upload)."
